/** Request generation and raw native observation. The independent Python oracle owns acceptance. */
abstract class DComponentCase {
 final JsonObject spec;final DChestCourierScene base;final ServerLevel level;final BlockPos origin;final Path evidence;final String id,group;final int number,quantity;final Item item;final UUID request;
 final Map<String,Container> extra=new LinkedHashMap<>();final Map<String,Entity> entities=new LinkedHashMap<>();final Map<String,Object> facts=new TreeMap<>();String phase="PREPARING";boolean terminal;int serial;long stepNs;
 DComponentCase(JsonObject spec,DChestCourierScene base,Path evidence){this.spec=spec;this.base=base;level=base.level;origin=base.arena.origin;this.evidence=evidence;id=spec.get("id").getAsString();group=spec.get("group").getAsString();number=Integer.parseInt(id.substring(id.length()-2));quantity=spec.get("quantity").getAsInt();item=net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(spec.get("item").getAsString()));request=DVillagerHandoffScene.id(id+"-original-request");entities.put("carrier",base.arena.actor);}
 abstract void prepare(Runnable next);abstract void execute(ServerPlayer player);
 void tick(){}void interfere(ServerPlayer p,String action){throw new IllegalStateException("no interference in "+id);}void stop(ServerPlayer p){throw new IllegalStateException("no stop");}void travelBudget(ServerPlayer p){throw new IllegalStateException("no travel campaign");}
 void clearWall(){for(int z=4;z<=10;z++)for(int y=0;y<3;y++)level.setBlockAndUpdate(origin.offset(8,y,z),Blocks.AIR.defaultBlockState());}
 Map<String,Container> containers(){var out=new LinkedHashMap<String,Container>();out.put("source",base.source());out.put("carrier",base.arena.actor.getInventory());out.put("destination",base.destination());out.putAll(extra);return out;}
 Container inspect(String role,ServerPlayer player){if(!containers().containsKey(role))throw new IllegalArgumentException("unknown actual role");return containers().get(role);}
 Map<String,Object> inspection(){var out=new LinkedHashMap<String,Object>();for(var e:containers().entrySet()){var c=e.getValue();List<? extends Number> pos=c instanceof BlockEntity b?List.of(b.getBlockPos().getX(),b.getBlockPos().getY(),b.getBlockPos().getZ()):List.of(base.arena.actor.getX(),base.arena.actor.getY(),base.arena.actor.getZ());for(var entity:entities.entrySet())if(entity.getKey().equals(e.getKey()))pos=List.of(entity.getValue().getX(),entity.getValue().getY(),entity.getValue().getZ());out.put(e.getKey(),Map.of("pos",pos,"slots",c.getContainerSize()));}return out;}
 void ready(){phase="READY";frame("BEFORE",null);var r=new TreeMap<String,Object>();r.put("case",id);r.put("actor",base.arena.actor.getUUID());r.put("citizen",base.arena.identity.citizen());r.put("origin",List.of(origin.getX(),origin.getY(),origin.getZ()));r.put("inspection",inspection());r.put("facts",facts);DComeScene.write(evidence.resolve("ready.json"),r);}
 void complete(Object detail){terminal=true;phase="TERMINAL";frame("TERMINAL",detail);DComeScene.write(evidence.resolve("terminal.json"),Map.of("case",id,"tick",level.getGameTime(),"phase",phase));}
 void operation(String kind,Object detail){frame(kind,detail);}
 void frame(String event,Object detail){var r=new TreeMap<String,Object>();r.put("case",id);r.put("group",group);r.put("case_seed",spec.get("case_seed").getAsLong());r.put("world_seed",level.getSeed());r.put("world",base.world);r.put("principal",base.scope.principal());r.put("actor",base.arena.actor.getUUID());r.put("request",request);r.put("tick",level.getGameTime());r.put("event",event);r.put("phase",phase);r.put("detail",detail);r.put("facts",facts);r.put("operation_label",id+"/native-observation/"+(++serial));r.put("integration_root",null);r.put("effect_id",null);r.put("save_proof",null);r.put("pid",ProcessHandle.current().pid());r.put("jvm_start_ms",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());r.put("forced_chunks",level.getChunkSource().getForceLoadedChunks().size());r.put("heap_used_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());r.put("step_ns",stepNs);r.put("native_feet",List.of(base.arena.actor.getX(),base.arena.actor.getY(),base.arena.actor.getZ()));r.put("native_navigation_done",base.arena.actor.getNavigation().isDone());
  var ent=new TreeMap<String,Object>();for(var e:entities.entrySet()){var v=e.getValue();ent.put(e.getKey(),Map.of("entity",v.getUUID(),"class",v.getClass().getName(),"pos",List.of(v.getX(),v.getY(),v.getZ()),"alive",v.isAlive(),"removed",v.isRemoved(),"loaded",level.getEntity(v.getUUID())==v && level.hasChunkAt(v.blockPosition()),"entity_ticks",v.tickCount));}r.put("entities",ent);
  if(!event.equals("MOVE")){var inventories=new LinkedHashMap<String,Object>();for(var e:containers().entrySet()){var c=e.getValue();var row=new TreeMap<String,Object>();boolean known=!(c instanceof RandomizableContainerBlockEntity b) || !b.isLocked() && b.getLootTable()==null;row.put("inventory_known",known);row.put("slots",known?base.stacks(c):null);row.put("native_class",c.getClass().getName());if(c instanceof BlockEntity b){row.put("pos",List.of(b.getBlockPos().getX(),b.getBlockPos().getY(),b.getBlockPos().getZ()));row.put("native_nbt",b.saveWithFullMetadata(level.registryAccess()).toString());row.put("block_state",b.getBlockState().toString());row.put("marker",b instanceof dev.aivillages.fabric.storage.StorageMarkerAccess m?m.cognitivecraft$marker():null);}inventories.put(e.getKey(),row);}r.put("inventories",inventories);var drops=new ArrayList<Map<String,Object>>();for(var e:level.getEntitiesOfClass(ItemEntity.class,new AABB(origin.getX()-2,origin.getY()-4,origin.getZ()-2,origin.getX()+24,origin.getY()+6,origin.getZ()+28)))drops.add(Map.of("entity",e.getUUID(),"item",base.reader.describeItem(e.getItem()),"count",e.getItem().getCount(),"pos",List.of(e.getX(),e.getY(),e.getZ())));r.put("item_entities",drops);}
  DComeScene.writeLine(evidence.resolve("frames.jsonl"),r);System.out.println("CC_D10_COMPONENT "+DComeScene.JSON.toJson(r));
 }
 void register(BlockPos pos,String adapter,String label,List<Grant> grants,Consumer<Binding> next){var caller=new Caller(base.world,DNativeScene.PRINCIPAL);DChestCourierScene.when(level,base.registry.registerMetadata(caller,base.registry.snapshot().revision(),new Owner(OwnerKind.PLAYER,DNativeScene.PRINCIPAL),id+"-"+label,adapter,Set.of(),grants),a->{DChestCourierScene.ack(a);base.identities.updateMetadata(base.registry.snapshot());bind(a.storage(),pos,next);});}
 void bind(UUID storage,BlockPos pos,Consumer<Binding> next){var plan=base.identities.plan(storage,base.registry.snapshot().records().get(storage).generation()+(base.registry.snapshot().bindings().containsKey(storage)?1:0),pos);var c=new Caller(base.world,DNativeScene.PRINCIPAL);var s=base.registry.snapshot();DChestCourierScene.when(level,base.registry.prepareBinding(c,s.revision(),storage,s.records().get(storage).revision(),plan.intent().wire()),a->{DChestCourierScene.ack(a);base.identities.updateMetadata(base.registry.snapshot());base.attested.set(base.identities.write(plan));synchronizeBinding(storage,next);});}
 void synchronizeBinding(UUID storage,Consumer<Binding> next){var s=base.registry.snapshot();DChestCourierScene.when(level,base.registry.acknowledgeBinding(new Caller(base.world,DNativeScene.PRINCIPAL),s.revision(),storage,s.records().get(storage).revision(),base.attested.get().wire()),a->{DChestCourierScene.ack(a);base.identities.updateMetadata(base.registry.snapshot());next.accept(base.identities.resolve(storage).orElseThrow());});}
 static Grant publicGrant(Permission... ops){return new Grant(new Owner(OwnerKind.PUBLIC,null),Set.of(ops));}
}
